function initials(name: string) { return name.split(' ').map((part) => part[0]).slice(0, 2).join(''); }
function dateLabel(value?: string | null, withTime = false) {
  if (!value) return '—';
  return new Intl.DateTimeFormat('fr-FR', withTime ? { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' } : { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value));
}
function timeLabel(value: string) { return new Intl.DateTimeFormat('fr-FR', { hour: '2-digit', minute: '2-digit' }).format(new Date(value)); }
function titleFor(path: string) { return ({ '/': 'Vue d’ensemble', '/dashboard': 'Vue d’ensemble', '/agenda': 'Agenda', '/clients': 'Clients', '/sessions/new': 'Nouvelle session', '/anatomie': 'Anatomie', '/exercices': 'Exercices', '/programmes': 'Programmes', '/facturation': 'Facturation', '/notifications': 'Notifications', '/parametres': 'Paramètres', '/client': 'Mon espace', '/admin': 'Administration' } as Record<string, string>)[path] || 'Dossier client'; }

