    <main className="min-h-[100dvh] md:pl-[245px]"><header className="sticky top-0 z-20 flex h-[72px] items-center border-b border-border/70 bg-background/90 px-5 backdrop-blur md:px-10"><button onClick={() => setMobileOpen(true)} className="mr-3 rounded-lg p-1.5 hover:bg-muted md:hidden" data-testid="button-open-mobile-nav"><Menu size={20} /></button><div className="flex-1"><p className="text-[11px] font-medium uppercase tracking-[.15em] text-muted-foreground">Jeudi 24 avril 2025</p><h1 className="text-[17px] font-semibold tracking-[-.02em]">{current}</h1></div><div className="flex items-center gap-2"><Link href="/notifications" className="relative grid size-9 place-items-center rounded-lg text-muted-foreground hover:bg-muted hover:text-foreground" data-testid="link-header-notifications"><Bell size={17} /><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-accent" /></Link><button className="hidden items-center gap-2 rounded-lg border border-border bg-card px-2.5 py-1.5 text-xs font-medium md:flex" data-testid="button-workspace-menu">Aline Laurent <ChevronDown size={14} className="text-muted-foreground" /></button></div></header><div className="mx-auto max-w-[1440px] px-5 py-8 md:px-10 lg:px-12">{children}</div></main>
